package com.sigtm.backend.service;
import com.sigtm.backend.dto.*; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class ReporteComprasService { private final OrdenCompraRepository orders; private final FacturaProveedorRepository invoices; private final PrecioProveedorRepository prices; private final ProductoRepository products;
 @Transactional(readOnly=true) public Map<String,Object> resumen(){List<OrdenCompra> o=orders.findAll(); List<FacturaProveedor> f=invoices.findAll(); BigDecimal committed=o.stream().filter(x->!"ANULADA".equals(x.getStatus())).map(OrdenCompra::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add); BigDecimal debt=f.stream().map(FacturaProveedor::getBalance).reduce(BigDecimal.ZERO,BigDecimal::add); return Map.of("orders",o.size(),"pendingApproval",o.stream().filter(x->"PENDIENTE_APROBACION".equals(x.getStatus())).count(),"partialReceipts",o.stream().filter(x->"PARCIAL".equals(x.getStatus())).count(),"committedAmount",committed,"openDebt",debt); }
 @Transactional(readOnly=true) public List<Map<String,Object>> porProveedor(){return orders.findAll().stream().filter(x->!"ANULADA".equals(x.getStatus())).collect(java.util.stream.Collectors.groupingBy(x->x.getSupplier().getBusinessName(),java.util.stream.Collectors.reducing(BigDecimal.ZERO,OrdenCompra::getTotal,BigDecimal::add))).entrySet().stream().map(e->Map.<String,Object>of("supplier",e.getKey(),"amount",e.getValue())).toList();}
 @Transactional(readOnly=true) public List<AlertaCuentaPorPagarResponse> alertasVencimiento(int days){LocalDate limit=LocalDate.now().plusDays(Math.max(0,days));return invoices.findAll().stream().filter(i->i.getBalance().signum()>0&&!"PAGADA".equals(i.getStatus())).filter(i->!i.getDueDate().isAfter(limit)).map(i->new AlertaCuentaPorPagarResponse(i.getId(),i.getNumber(),i.getPurchaseOrder().getSupplier().getBusinessName(),i.getDueDate(),i.getBalance(),i.getDueDate().isBefore(LocalDate.now())?"VENCIDA":"PROXIMA")).sorted(Comparator.comparing(AlertaCuentaPorPagarResponse::dueDate)).toList();}
 @Transactional(readOnly=true) public List<TendenciaCostoResponse> tendencias(){return products.findByActiveTrue().stream().map(p->{var offers=prices.findByProductIdAndActiveTrueOrderByUnitPriceAsc(p.getId());BigDecimal low=offers.isEmpty()?p.getPurchasePrice():offers.getFirst().getUnitPrice();BigDecimal current=p.getPurchasePrice();BigDecimal diff=current.signum()==0?BigDecimal.ZERO:low.subtract(current).multiply(BigDecimal.valueOf(100)).divide(current,2,RoundingMode.HALF_UP);return new TendenciaCostoResponse(p.getId(),p.getCode(),p.getName(),current,low,diff,diff.signum()<0?"AHORRO_DISPONIBLE":"ESTABLE");}).toList();}
}
